def slow(A):                       # brute force: count each value, O(N^2)
    for x in A:
        if A.count(x) % 2 == 1:
            return x

def fast(A):                       # XOR: pairs cancel, O(N) time, O(1) space
    acc = 0
    for x in A:
        acc ^= x
    return acc

for A in [[9, 3, 9, 3, 9, 7, 9], [4, 1, 2, 1, 2], [42]]:
    print(slow(A), fast(A))        # -> 7 7, then 4 4, then 42 42
